import{_ as s,c as i,o as t,aj as a}from"./chunks/framework.B-K7myP5.js";const k=JSON.parse('{"title":"K3s 证书过期问题","description":"Unable to connect to the server x509 certificate has expired or is not yet valid","frontmatter":{"title":"K3s 证书过期问题","createTime":"2024/01/11 14:34:04","permalink":"/article/k3s-certificate-expired/","tags":["Kubernetes"],"description":"Unable to connect to the server x509 certificate has expired or is not yet valid","lastUpdated":"2026-01-22","link":"/posts/k3s-certificate-expired","layout":"doc","prev":{"text":"Windows编写的sh脚本在Linux上运行失败","link":"/posts/sh-bad-interpreter"},"next":{"text":"K3s 安装","link":"/posts/k3s-setup"}},"headers":[],"params":{"pkg":"k3s-certificate-expired"},"relativePath":"posts/k3s-certificate-expired.md","filePath":"posts/[pkg].md"}'),l={name:"posts/k3s-certificate-expired.md"};function n(r,e,o,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Unable to connect to the server: x509: certificate has expired or is not yet valid: current time 2019-02-03T07:40:33+08:00 is before 2022-03-10T09:56:33Z</span></span></code></pre></div><h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to “原因”">​</a></h2><p>报错提示很明显，证书已过期或尚未生效.</p><p>上面报错：主机时间 <code>2019-02-03</code>，证书时间 <code>2022-03-10</code>，主机时间与证书时间不匹配，导致证书不生效.</p><h2 id="处理" tabindex="-1">处理 <a class="header-anchor" href="#处理" aria-label="Permalink to “处理”">​</a></h2><ol><li>修改主机时间</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date -s 20220316	// 修改日期</span></span>\n<span class="line"><span>date -s 17:11:00	// 修改时间</span></span>\n<span class="line"><span>clock --systohc		// 把系统时间回存到硬件时钟</span></span></code></pre></div><ol start="2"><li>删除 <code>K3s</code> 证书</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -fr /var/lib/rancher/k3s/server/tls</span></span></code></pre></div><blockquote><p><code>K3s</code> 会自动创建证书，删除所有的证书后，<code>K3s</code> 重启时会根据当前时间再次创建证书.</p></blockquote><ol start="3"><li>重启 <code>K3s</code></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start k3s</span></span></code></pre></div><ol start="4"><li>验证，查看 <code>K3s</code> 证书过期时间</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in `ls /var/lib/rancher/k3s/server/tls/*.crt`; do echo $i; openssl x509 -enddate -noout -in $i; done</span></span></code></pre></div>',15)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
